head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[linkedDataList > M > getRealRowIndex]<br/>LinkedDataList 모듈의 Row 인덱스값을 사용하여 특정 Row 의 원본(Origin) 인덱스값을 반환합니다.",
    "validation" : [
        "rowIndex(필수) 파라미터로 원본(Origin) 인덱스값을 조회하려는 Row 의 인덱스값을 숫자로 설정합니다.",
        "Row 의 인덱스는 0 부터 시작하며 LinkedDataList 모듈의 필터/정렬 설정에 맞게 인덱스를 설정합니다.",
        "반환값으로 파라미터에 해당하는 Row 의 원본(Origin) 인덱스값을 반환합니다.",
        "필터/정렬이 적용되지 않은 원본 DataList 모듈의 Row 인덱스값을 반환합니다.",
        "파라미터에 해당하는 Row 가 없는 경우 undefined 를 반환합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
	// 기존 target 있으면 삭제
    if (typeof gdl_org !== 'undefined') {
        $p.data.remove("gdl_org");
    }

    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }   

    if (typeof gridView2 !== 'undefined') {
        gridView2.remove();
    }   

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

	// target 생성
    $c.gcm.createOrginalDataList();
    $c.gcm.createBasicLinkedDataList();

    // gridView 생성
    let grp_comp = document.querySelector('.tc_group_basic');   
    let strGridView1 = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strGridView1 += '<w2:gridView ' + strNameSpace + ' autoFit="allColumn" checkAllType="false" dataList="data:gdl_org" rowStatusVisible="true" sortable="true" style="width:500px; height:200px;" focusMode="row" syncRowPositionOption="style">'
    strGridView1 += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>'
    strGridView1 += '<w2:header style="" id="header1">'
    strGridView1 += '<w2:row style="" id="row1">'
    strGridView1 += '<w2:column width="70" style="" inputType="text" id="column4" value="cat1"></w2:column>'
    strGridView1 += '<w2:column width="70" style="" inputType="text" id="column3" value="cat2" useFilter=""></w2:column>'
    strGridView1 += '<w2:column width="70" style="" inputType="text" id="column2" value="label"></w2:column>'
    strGridView1 += '<w2:column width="70" style="" inputType="text" id="column1" value="value"></w2:column>'
    strGridView1 += '</w2:row>'
    strGridView1 += '</w2:header>'
    strGridView1 += '<w2:gBody style="" id="gBody1">'
    strGridView1 += '<w2:row style="" id="row2">'
    strGridView1 += '<w2:column width="70" style="" inputType="text" id="cat1" value=""></w2:column>'
    strGridView1 += '<w2:column width="70" style="" inputType="text" id="cat2" value=""></w2:column>'
    strGridView1 += '<w2:column width="70" style="" inputType="text" id="label" value=""></w2:column>'
    strGridView1 += '<w2:column width="70" style="" inputType="text" id="value" value=""></w2:column>'
    strGridView1 += '</w2:row>'
    strGridView1 += '</w2:gBody>'
    strGridView1 += '</w2:gridView>'

    // target 생성
    scwin["gridView1"] = await $p.dynamicCreate(
        "gridView1",
        "gridView",
        strGridView1,
        grp_comp
    );

    // org DataList 선택
    gdl_org.setRowPosition(4);

    $c.gcm.createLinkedGridView();
}   



scwin.btn_setColumnFilter_onclick = function (e) {
	target1.setColumnFilter({type:"row", colIndex:"value", key:"BB11", condition:"and"});
    target1.setColumnFilter({type:"row", colIndex:"value", key:"BB21", condition:"or"});
};



scwin.btn_sort_onclick = function (e) {
    target1.sort("label", 1);
};



scwin.btn_getRealRowIndex_onclick = function (e) {
    let rowIndex = par_rowIndex.getText();
    let rtn = target1.getRealRowIndex(Number(rowIndex));

    wf_body_bottom.getObj("scwin").setReturnValue("result: " + rtn);
};
